async function api(path, options = {}) {
  const method = String(options.method || 'GET').toUpperCase(), headers = { ...(options.headers || {}) };
  if (options.body) headers['Content-Type'] = 'application/json';
  if (csrfToken && !['GET', 'HEAD'].includes(method)) headers['X-CSRF-Token'] = csrfToken;
  const response = await fetch(path, { ...options, method, headers });
  const value = response.status === 204 ? null : await response.json();
  if (!response.ok) { const failure = new Error(value?.error || `Request failed (${response.status}).`); failure.status = response.status; if (response.status === 401 && currentUser) { currentUser = null; csrfToken = ''; showLogin('Your session expired. Sign in again.'); } throw failure; }
  return value;
}
async function refresh() { state = await api('/api/state'); updateBadges(); }
function updateBadges() { $('#leadCount').textContent = state.leads.filter(row => !['Confirmed', 'Lost'].includes(row.status)).length; $('#visaCount').textContent = state.visas.filter(row => !['Approved', 'Rejected'].includes(row.status)).length; const count = upcomingTrips().length; $('#notificationsButton').dataset.count = count || ''; $('#notificationsButton').title = count ? `${count} trip reminder${count === 1 ? '' : 's'} due` : 'Operational notifications'; }
function toast(message) { const element = $('#toast'); element.textContent = message; element.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => element.classList.remove('show'), 3200); }
function showModal(title, body, footer = '<button class="btn" data-close-modal>Close</button>', locked = false) { $('#modalTitle').textContent = title; $('#modalBody').innerHTML = body; $('#modalFooter').innerHTML = footer; $('#modal').dataset.locked = locked ? 'true' : ''; $('#modal [data-close-modal]').classList.toggle('hidden', locked); $('#modal').classList.add('open'); $('#modal .modal').scrollTop = 0; }
function closeModal() { if ($('#modal').dataset.locked === 'true') return; $('#modal').classList.remove('open'); }
const isAdmin = () => currentUser?.role === 'admin';
const allowedPages = () => isAdmin() ? ['discover', 'dashboard', 'leads', 'quotations', 'packages', 'customers', 'bookings', 'visas', 'payments', 'suppliers', 'staff', 'reports', 'settings'] : ['discover', 'dashboard', 'leads', 'quotations', 'packages', 'customers', 'bookings', 'visas'];
function showLogin(message = '') { $('#appShell').classList.add('hidden'); $('#loginView').classList.remove('hidden'); $('#loginError').textContent = message; $('#loginForm').reset(); $('#loginForm [name="username"]').focus(); $('#modal').classList.remove('open'); }
function showApp() { $('#loginView').classList.add('hidden'); $('#appShell').classList.remove('hidden'); $$('[data-admin-only]').forEach(element => element.classList.toggle('hidden', !isAdmin())); $('#profileName').textContent = currentUser.displayName; $('#profileRole').textContent = currentUser.role === 'admin' ? 'Administrator' : 'Employee'; $('#profileInitials').textContent = currentUser.displayName.split(/\s+/).map(part => part[0]).join('').slice(0, 2).toUpperCase(); if (!allowedPages().includes(currentPage)) currentPage = 'dashboard'; }
function passwordForm(forced = false) { showModal(forced ? 'Secure your account' : 'Change password', `<p>${forced ? 'Replace the one-time password before entering the CRM.' : 'Use a unique password with at least 12 characters.'}</p><form id="passwordForm" class="form-grid">${forced ? '' : '<label class="full">Current password<input name="currentPassword" type="password" autocomplete="current-password" required></label>'}<label>New password<input name="newPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><label>Confirm password<input name="confirmPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><p class="error full" id="passwordError"></p></form>`, forced ? '<button class="btn primary" type="submit" form="passwordForm">Set password and continue</button>' : '<button class="btn" data-close-modal>Cancel</button><button class="btn primary" type="submit" form="passwordForm">Update password</button>', forced); }
function showAccount() { showModal('Account & security', `<div class="account-summary"><i>${escapeHTML($('#profileInitials').textContent)}</i><div><h3>${escapeHTML(currentUser.displayName)}</h3><p>${escapeHTML(currentUser.username)} · ${escapeHTML(currentUser.role)}</p></div></div><p class="muted">Sessions expire after 30 minutes of inactivity and after eight hours maximum.</p>`, '<button class="btn" data-change-password>Change password</button><button class="btn danger" data-logout>Sign out</button>'); }
function pageHead(title, description, actions = '') { return `<header class="page-head"><div><h1>${escapeHTML(title)}</h1><p>${escapeHTML(description)}</p></div><div class="actions">${actions}</div></header>`; }
function status(value) { return `<span class="status ${slug(value)}">${escapeHTML(value)}</span>`; }
function table(headings, rows) { return `<div class="table-wrap"><table><thead><tr>${headings.map(item => `<th>${escapeHTML(item)}</th>`).join('')}</tr></thead><tbody>${rows.length ? rows.map(row => `<tr>${row.map(cell => `<td>${cell}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${headings.length}" class="empty">No records yet.</td></tr>`}</tbody></table></div>`; }
function stats(items) { return `<div class="stats">${items.map(([label, value]) => `<article class="stat"><span>${escapeHTML(label)}</span><b>${escapeHTML(value)}</b></article>`).join('')}</div>`; }

const fieldSchemas = {
  leads: [field('name', 'Name'), field('phone', 'Phone', 'tel'), field('destination', 'Destination'), field('date', 'Travel date', 'date'), field('source', 'Source', ['Website', 'WhatsApp', 'Instagram', 'Referral']), field('owner', 'Owner', ['Snehal', 'Amit', 'Neha', 'Unassigned']), field('followup', 'Follow-up date', 'date', true), field('status', 'Status', ['New', 'Follow-up', 'Quotation', 'Confirmed', 'Lost'])],
  customers: [field('name', 'Full name'), field('phone', 'Mobile', 'tel'), field('documents', 'Document notes', 'text', true), field('lastTrip', 'Last trip', 'text', true)],
  bookings: [field('customer', 'Customer'), field('phone', 'Mobile', 'tel'), field('trip', 'Destination'), field('type', 'Trip type', ['Domestic', 'International']), field('services', 'Services'), field('departure', 'Departure', 'date'), field('return', 'Return', 'date'), field('total', 'Total value', 'money'), field('taxRate', 'Tax rate %', 'number'), field('status', 'Status', ['Pending', 'Confirmed', 'Cancelled']), field('stage', 'Stage (1–5)', 'integer'), field('invoice', 'Invoice number', 'text', true)],
  visas: [field('applicant', 'Applicant'), field('country', 'Country'), field('appointment', 'Appointment', 'date', true), field('fee', 'Visa fee', 'money'), field('total', 'Checklist total', 'integer'), field('done', 'Documents complete', 'integer'), field('status', 'Status', ['Documents pending', 'Appointment booked', 'Submitted', 'Approved', 'Rejected'])],
  suppliers: [field('name', 'Supplier name'), field('type', 'Type', ['Hotel', 'DMC', 'Transport', 'Airline', 'Other']), field('location', 'Location'), field('lastRate', 'Saved rate', 'money'), field('outstanding', 'Outstanding', 'money'), field('rating', 'Rating (0–5)', 'number'), field('status', 'Availability', ['Available', 'Limited', 'Unavailable'])],
  packages: [field('name', 'Package name'), field('destination', 'Destination'), field('duration', 'Duration'), field('nights', 'Nights', 'integer'), field('route', 'Route'), field('price', 'Price per person', 'money'), field('type', 'Trip type', ['Domestic', 'International']), field('theme', 'Travel style', ['Family', 'Honeymoon', 'Adventure', 'Culture']), field('flights', 'Flights', ['Included', 'Not included']), field('stars', 'Hotel stars', 'number'), field('color', 'Card colour', ['japan', 'kashmir', 'bali', 'dubai', 'kerala']), field('tagline', 'Highlight'), field('itinerary', 'Day-wise itinerary', 'textarea'), field('details', 'Inclusions and exclusions', 'textarea')],
  payments: [field('invoice', 'Invoice number'), field('customer', 'Customer'), field('total', 'Invoice total', 'money'), field('received', 'Opening received', 'money'), field('due', 'Due date', 'date')]
};
function field(key, label, type = 'text', optional = false) { return { key, label, type, optional }; }
function fieldControl(spec, value = '') {
  const required = spec.optional ? '' : 'required', safe = escapeHTML(value);
  if (spec.key === 'stage') return `<div class="stage-picker" role="radiogroup" aria-label="Booking stage">${[1, 2, 3, 4, 5].map(stage => `<label><input type="radio" name="stage" value="${stage}" ${Number(value) === stage ? 'checked' : ''} required><span>${stage}</span></label>`).join('')}</div>`;
  if (Array.isArray(spec.type)) return `<select name="${spec.key}" ${required}>${spec.type.map(option => `<option ${String(option) === String(value) ? 'selected' : ''}>${escapeHTML(option)}</option>`).join('')}</select>`;
  if (spec.type === 'textarea') return `<textarea name="${spec.key}" rows="5" ${required}>${safe}</textarea>`;
  const type = spec.type === 'money' ? 'text' : spec.type === 'integer' || spec.type === 'number' ? 'number' : spec.type;
  const attributes = spec.type === 'money' ? 'inputmode="decimal" placeholder="e.g. 1,50,000.50"' : spec.type === 'integer' ? 'step="1" min="0"' : spec.type === 'number' ? 'step="0.01" min="0"' : '';
  return `<input name="${spec.key}" type="${type}" value="${safe}" ${attributes} ${required}>`;
}
function schemaFor(collection) { return !isAdmin() && collection === 'bookings' ? fieldSchemas.bookings.filter(spec => !['total', 'taxRate', 'status', 'invoice'].includes(spec.key)) : fieldSchemas[collection]; }
function openEditor(collection, id = '', preset = {}) {
  if (!allowedPages().includes(collection === 'packages' ? 'packages' : collection)) return toast('Your role cannot edit this section.');
  const existing = id ? state[collection].find(row => row.id === id) : null;
  const defaults = { leads: { source: 'Website', owner: 'Snehal', status: 'New', date: plusDays(today(), 30), followup: today() }, bookings: { type: 'Domestic', departure: plusDays(today(), 30), return: plusDays(today(), 35), total: 0, taxRate: 5, status: 'Pending', stage: 1, invoice: '' }, visas: { appointment: '', fee: 0, total: 7, done: 0, status: 'Documents pending' }, suppliers: { type: 'Hotel', lastRate: 0, outstanding: 0, rating: 4, status: 'Available' }, packages: { nights: 4, duration: '4N / 5D', price: 0, type: 'Domestic', theme: 'Family', flights: 'Not included', stars: 3, color: 'kerala', itinerary: 'Arrival|Pickup and check-in.\nExplore|Local sightseeing and leisure.\nDeparture|Breakfast and transfer.', details: 'Supplier rates, inclusions and availability require confirmation.' }, payments: { total: 0, received: 0, due: plusDays(today(), 14) } };
  const record = { ...(defaults[collection] || {}), ...(existing || {}), ...preset };
  showModal(`${existing ? 'Edit' : 'Add'} ${collection.slice(0, -1)}`, `<form id="editorForm" class="form-grid" data-collection="${collection}" data-id="${escapeHTML(id)}">${schemaFor(collection).map(spec => `<label class="${spec.type === 'textarea' ? 'full' : ''}">${escapeHTML(spec.label)}${fieldControl(spec, record[spec.key] ?? '')}</label>`).join('')}<p class="error full" id="editorError"></p></form>`, `<button class="btn" data-close-modal>Cancel</button><button class="btn primary" type="submit" form="editorForm">${existing ? 'Save changes' : 'Create'}</button>`);
}
function formRecord(form) { const value = Object.fromEntries(new FormData(form)); for (const spec of schemaFor(form.dataset.collection)) if (['integer', 'number', 'money'].includes(spec.type)) value[spec.key] = spec.type === 'money' ? parseRupees(value[spec.key]) : Number(value[spec.key]); return value; }

function render() {
  if (!allowedPages().includes(currentPage)) currentPage = 'dashboard';
  const renderers = { discover: renderDiscover, dashboard: renderDashboard, leads: renderLeads, quotations: renderQuote, packages: renderPackages, customers: renderCustomers, bookings: renderBookings, visas: renderVisas, payments: renderPayments, suppliers: renderSuppliers, staff: renderStaff, reports: renderReports, settings: renderSettings };
  $('#page').innerHTML = renderers[currentPage]();
  const titles = { discover: 'Travel desk', dashboard: 'Dashboard', leads: 'Leads', quotations: 'Quotations', packages: 'Packages', customers: 'Customers', bookings: 'Bookings', visas: 'Visa cases', payments: 'Payments', suppliers: 'Suppliers', staff: 'Staff', reports: 'Reports', settings: 'Settings' };
  $('#pageName').textContent = titles[currentPage];
  $('#globalSearch').placeholder = ['discover', 'packages'].includes(currentPage) ? 'Search holiday packages…' : 'Search CRM records…';
  $$('.nav,.mobile-nav button').forEach(button => button.classList.toggle('active', button.dataset.page === currentPage));
}
function navigate(page) { if (!allowedPages().includes(page)) return toast('Your role does not have access to that section.'); currentPage = page; $('#sidebar').classList.remove('open'); render(); $('#page').focus({ preventScroll: true }); scrollTo(0, 0); }

function renderDashboard() {
  const attention = [...upcomingTrips().map(row => `<div class="activity reminder"><span class="dot"></span><div><p><b>${escapeHTML(row.customer)}</b> · trip reminder due</p><small>${escapeHTML(row.trip)} · departs ${dateText(row.departure)}</small></div></div>`), ...state.bookings.filter(row => row.status === 'Pending').map(row => `<div class="activity"><span class="dot"></span><div><p><b>${escapeHTML(row.customer)}</b> · pending booking</p><small>${escapeHTML(row.trip)} · ${dateText(row.departure)}</small></div></div>`), ...state.visas.filter(row => !['Approved', 'Rejected'].includes(row.status)).slice(0, 3).map(row => `<div class="activity"><span class="dot"></span><div><p><b>${escapeHTML(row.applicant)}</b> · ${escapeHTML(row.status)}</p><small>${escapeHTML(row.country)} visa tracking</small></div></div>`)];
  const attentionCard = `<section class="card"><div class="card-title"><h2>Needs attention</h2><button class="btn small" data-page="bookings">Open operations</button></div><div class="attention-scroll">${attention.join('') || '<p class="empty">Nothing needs attention.</p>'}</div></section>`;
  if (!isAdmin()) {
    const statusCounts = ['New', 'Follow-up', 'Quotation', 'Confirmed'].map(label => [label, state.leads.filter(row => row.status === label).length]), max = Math.max(...statusCounts.map(([, value]) => value), 1);
    return pageHead(`Good evening, ${currentUser.displayName}`, 'Your operational workspace. Financial and management data are restricted.', '<button class="btn primary" data-add="leads">＋ New lead</button>') + stats([['Active leads', state.leads.filter(row => !['Confirmed', 'Lost'].includes(row.status)).length], ['Pending bookings', state.bookings.filter(row => row.status === 'Pending').length], ['Active visa cases', state.visas.filter(row => !['Approved', 'Rejected'].includes(row.status)).length], ['Packages', state.packages.length]]) + `<div class="grid-2"><section class="card"><div class="card-title"><h2>Lead pipeline</h2><span class="muted">Live operational counts</span></div><div class="bar-chart">${statusCounts.map(([label, value]) => `<div class="bar h-${Math.round(value / max * 10) * 10}" data-value="${value}"><i>${label}</i></div>`).join('')}</div></section>${attentionCard}</div>`;
  }
  const revenue = sum(state.payments, row => row.received), outstanding = sum(state.payments, row => row.total - row.received);
  const months = [...Array(6)].map((_, index) => { const date = new Date(); date.setUTCMonth(date.getUTCMonth() + index); return { key: date.toISOString().slice(0, 7), label: new Intl.DateTimeFormat('en-IN', { month: 'short', timeZone: 'UTC' }).format(date) }; });
  const monthValues = months.map(month => sum(state.bookings.filter(row => row.status === 'Confirmed' && row.departure.startsWith(month.key)), row => row.total)), max = Math.max(...monthValues, 1);
  return pageHead(`Good evening, ${currentUser.displayName}`, 'Live position calculated from connected CRM records.', '<button class="btn primary" data-add="leads">＋ New lead</button>') + stats([['Active leads', state.leads.filter(row => !['Confirmed', 'Lost'].includes(row.status)).length], ['Confirmed bookings', state.bookings.filter(row => row.status === 'Confirmed').length], ['Revenue received', money(revenue)], ['Outstanding', money(outstanding)]]) + `<div class="grid-2"><section class="card"><div class="card-title"><h2>Confirmed booking value</h2><span class="muted">Next six departure months</span></div><div class="bar-chart">${monthValues.map((value, index) => `<div class="bar h-${Math.round(value / max * 10) * 10}" data-value="${money(value)}"><i>${months[index].label}</i></div>`).join('')}</div></section>${attentionCard}</div>`;
}

function travelForm() {
  const future = plusDays(today(), 30), back = plusDays(today(), 35), services = [['holidays', '⌂ Holidays'], ['flights', '✈ Flights'], ['hotels', '▥ Hotels'], ['cabs', '▣ Cabs'], ['trains', '▤ Trains'], ['bus', '▥ Bus']];
  return `<form class="travel-search" id="travelForm"><div class="service-tabs" role="tablist">${services.map(([key, label]) => `<button type="button" role="tab" aria-selected="${travelMode === key}" class="service-tab ${travelMode === key ? 'active' : ''}" data-travel-mode="${key}">${label}</button>`).join('')}</div>${travelMode === 'flights' ? `<div class="trip-options"><label><input type="radio" name="trip" value="oneway" checked>One way</label><label><input type="radio" name="trip" value="return">Round trip</label><label><input type="radio" name="trip" value="multi">Multi-city</label><span class="muted">Planning estimates · no live inventory</span></div>` : ''}<div class="search-fields"><label class="search-field"><span>Starting from</span><input name="from" value="Pune" list="cities" required></label><label class="search-field"><span>${travelMode === 'hotels' ? 'Where to stay?' : 'Where to?'}</span><input name="to" value="${travelMode === 'holidays' ? '' : travelMode === 'hotels' ? 'Kerala' : travelMode === 'flights' ? 'Delhi' : 'Mumbai'}" list="destinations" ${travelMode === 'holidays' ? '' : 'required'} placeholder="${travelMode === 'holidays' ? 'Anywhere' : 'Destination'}"></label><label class="search-field"><span>${travelMode === 'hotels' ? 'Check-in' : 'Departure'}</span><input name="departure" type="date" min="${today()}" value="${future}" required></label><label class="search-field"><span>Travellers</span><input value="2 adults" aria-label="Traveller summary" readonly></label><button class="search-button">${travelMode === 'holidays' ? 'Search holidays' : ['trains', 'bus'].includes(travelMode) ? 'Plan enquiry' : `Search ${escapeHTML(travelMode)}`}</button></div><div class="traveller-fields"><label>Adults <input name="adults" type="number" min="1" max="20" value="2"></label><label>Children <input name="children" type="number" min="0" max="10" value="0"></label>${travelMode === 'flights' ? '<label>Infants <input name="infants" type="number" min="0" max="10" value="0"></label><label>Cabin <select name="cabin"><option>Economy</option><option>Premium economy</option><option>Business</option></select></label>' : ''}${['holidays', 'hotels'].includes(travelMode) ? '<label>Rooms <input name="rooms" type="number" min="1" max="20" value="1"></label>' : ''}</div><div id="returnFields" class="return-fields ${travelMode === 'hotels' ? '' : 'hidden'}"><label>${travelMode === 'hotels' ? 'Check-out' : 'Return'} <input name="returnDate" type="date" min="${future}" value="${back}"></label></div><div id="multiFields">${travelMode === 'flights' && travelLegs.length ? travelLegs.map((leg, index) => `<div class="traveller-fields"><label>Leg ${index + 2} from <input name="legFrom${index}" value="${escapeHTML(leg.from)}" list="cities"></label><label>To <input name="legTo${index}" value="${escapeHTML(leg.to)}" list="cities"></label><label>Date <input name="legDate${index}" type="date" min="${future}" value="${escapeHTML(leg.date)}"></label><button class="btn small" type="button" data-remove-leg="${index}">Remove leg</button></div>`).join('') : ''}</div>${travelMode === 'flights' ? '<button class="btn small hidden" id="addLegButton" type="button" data-add-leg>＋ Add city</button>' : ''}<p class="error" id="travelError"></p><div class="recent"><span>Recent:</span>${(state.explorer.recent || []).slice(0, 5).map((row, index) => `<button type="button" data-recent="${index}">${escapeHTML(row.from)} → ${escapeHTML(row.to || 'Anywhere')} · ${escapeHTML(row.mode)}</button>`).join('') || '<span>Your next adventure is waiting.</span>'}</div><datalist id="cities"><option>Pune</option><option>Mumbai</option><option>Delhi</option><option>Bengaluru</option><option>Kochi</option><option>Srinagar</option><option>Goa</option><option>Dubai</option><option>Tokyo</option><option>Bali</option><option>Singapore</option><option>Agra</option><option>Lonavala</option></datalist><datalist id="destinations"><option>Japan</option><option>Kashmir</option><option>Kerala</option><option>Dubai</option><option>Bali</option><option>Tokyo</option><option>Srinagar</option><option>Kochi</option><option>Delhi</option><option>Mumbai</option><option>Goa</option><option>Bengaluru</option><option>Singapore</option></datalist></form>`;
}
function filteredPackages() {
  let rows = state.packages.filter(row => (!packageFilter.query || [row.name, row.destination, row.route, row.theme].join(' ').toLowerCase().includes(packageFilter.query.toLowerCase())) && row.price <= packageFilter.budget && (packageFilter.type === 'All' || row.type === packageFilter.type) && (packageFilter.theme === 'All' || row.theme === packageFilter.theme) && (packageFilter.flights === 'All' || row.flights === packageFilter.flights) && (packageFilter.duration === 'All' || packageFilter.duration === 'Short' && row.nights <= 4 || packageFilter.duration === 'Medium' && row.nights >= 5 && row.nights <= 7 || packageFilter.duration === 'Long' && row.nights >= 8) && (!packageFilter.savedOnly || state.explorer.saved.includes(row.id)));
  if (packageFilter.sort === 'priceLow') rows.sort((a, b) => a.price - b.price); if (packageFilter.sort === 'priceHigh') rows.sort((a, b) => b.price - a.price); if (packageFilter.sort === 'duration') rows.sort((a, b) => a.nights - b.nights); return rows;
}
function packageCards(rows) { return rows.length ? rows.map(row => `<article class="card package-card"><div class="package-image ${escapeHTML(row.color)}"><img src="${escapeHTML(packagePhoto(row))}" alt="${escapeHTML(row.destination)} destination scenery" loading="lazy"><b>${escapeHTML(row.destination)} · ${escapeHTML(row.type)}</b><button type="button" class="save-button ${state.explorer.saved.includes(row.id) ? 'saved' : ''}" data-save-package="${escapeHTML(row.id)}" aria-label="${state.explorer.saved.includes(row.id) ? 'Unsave' : 'Save'} ${escapeHTML(row.name)}">${state.explorer.saved.includes(row.id) ? '♥' : '♡'}</button></div><div class="package-body"><h3>${escapeHTML(row.name)}</h3><p class="route">${escapeHTML(row.route)}</p><div class="includes"><span>${row.stars}★ hotels</span><span>${escapeHTML(row.flights)}</span><span>Breakfast</span></div><p class="tagline">✓ ${escapeHTML(row.tagline)}</p><div class="package-bottom"><div class="price"><small>Illustrative price / person</small><strong>${money(row.price)}</strong><small>Before tax</small></div><button class="btn blue small" data-package-details="${escapeHTML(row.id)}">View package →</button></div><label class="compare"><input type="checkbox" data-compare-package="${escapeHTML(row.id)}" ${selectedPackages.has(row.id) ? 'checked' : ''}>Compare</label></div></article>`).join('') : '<div class="card empty">No packages match these filters.</div>'; }
function travelResults() {
  if (travelMode === 'holidays') { const rows = filteredPackages(); return `<div class="results-head"><div><h2>${packageFilter.savedOnly ? 'Saved getaways' : 'Find your kind of getaway'}</h2><p>${rows.length} package${rows.length === 1 ? '' : 's'} · prices per person before tax</p></div><div class="actions"><button class="btn ${packageFilter.savedOnly ? 'blue' : ''}" data-saved-filter>♡ Saved ${state.explorer.saved.length}</button><select class="field" id="packageSort"><option value="recommended">Recommended</option><option value="priceLow" ${packageFilter.sort === 'priceLow' ? 'selected' : ''}>Price: Low to high</option><option value="priceHigh" ${packageFilter.sort === 'priceHigh' ? 'selected' : ''}>Price: High to low</option><option value="duration" ${packageFilter.sort === 'duration' ? 'selected' : ''}>Shortest first</option></select>${selectedPackages.size >= 2 ? `<button class="btn blue" data-compare-selected>Compare ${selectedPackages.size}</button>` : ''}</div></div><div class="explore"><aside class="card filter-panel"><details open><summary><b>Filter your trip</b></summary><div class="filter-body"><div class="filter-group"><label>Maximum budget</label><input class="field" id="budgetFilter" inputmode="decimal" value="${Number(packageFilter.budget).toLocaleString('en-IN')}"></div><div class="filter-group"><label>Duration</label><select class="field" id="durationFilter">${['All', 'Short', 'Medium', 'Long'].map(value => `<option ${packageFilter.duration === value ? 'selected' : ''}>${value}</option>`).join('')}</select></div><div class="filter-group"><label>Destination type</label><select class="field" id="typeFilter">${['All', 'Domestic', 'International'].map(value => `<option ${packageFilter.type === value ? 'selected' : ''}>${value}</option>`).join('')}</select></div><div class="filter-group"><label>Travel style</label><select class="field" id="themeFilter">${['All', 'Family', 'Honeymoon', 'Adventure', 'Culture'].map(value => `<option ${packageFilter.theme === value ? 'selected' : ''}>${value}</option>`).join('')}</select></div><div class="filter-group"><label>Flights</label><select class="field" id="flightFilter">${['All', 'Included', 'Not included'].map(value => `<option ${packageFilter.flights === value ? 'selected' : ''}>${value}</option>`).join('')}</select></div><button class="btn small" data-clear-package-filter>Reset filters</button></div></details></aside><div class="package-grid">${packageCards(rows)}</div></div>`; }
  if (!travelEstimate) return `<div class="results-head"><div><h2>${travelMode === 'hotels' ? 'Find your stay' : travelMode === 'cabs' ? 'Make the connection' : `Plan ${travelMode}`}</h2><p>Choose your route and search for an estimate.</p></div></div><div class="card empty">No live availability is connected. Search to build a planning estimate.</div>`;
  if (travelEstimate.manual) return `<div class="results-head"><div><h2>Manual supplier enquiry</h2><p>${escapeHTML(travelEstimate.from)} → ${escapeHTML(travelEstimate.to)}</p></div></div><div class="info">${escapeHTML(travelEstimate.message)}</div><form id="manualEstimateForm" class="card manual-form"><label>Service / supplier note<input class="field" name="name" placeholder="e.g. AC sleeper · supplier reference" required></label><label>Total before tax<input class="field" name="amount" inputmode="decimal" placeholder="₹12,500.00" required></label><button class="btn primary">Prepare quotation</button></form>`;
  return `<div class="results-head"><div><h2>Planning estimates</h2><p>Total for selected travellers · before tax</p></div></div><div class="info">These are planning allowances, not live offers. Confirm the supplier, availability, terms and applicable tax before sharing.</div><div class="service-results">${travelEstimate.offers.map((offer, index) => `<article class="card service-offer"><div><small class="status quotation">PLANNING ESTIMATE</small><h3>${escapeHTML(offer.name)}</h3><p class="muted">${escapeHTML(offer.basis)}</p></div><div><b>${escapeHTML(offer.route)}</b><p class="muted">${dateText(travelEstimate.departure)}</p></div><div class="price"><strong>${money(offer.price)}</strong><small>Total · before tax</small><div><button class="btn primary small" data-offer-quote="${index}">Make quotation</button> <button class="btn small" data-offer-book="${index}">Create booking</button></div></div></article>`).join('')}</div>`;
}
function renderDiscover() { return `<section class="travel-hero"><small>Hindavi connected travel desk</small><h1>A great trip starts here.</h1><p>Find the journey, make it personal, and carry every detail into your CRM.</p></section>${travelForm()}<p class="travel-note">Planning prototype · package prices and service estimates require supplier confirmation.</p><div class="collections"><button class="collection" data-collection="budget"><i>₹</i><span><b>Big memories. Thoughtful budgets.</b><small>Getaways under ₹50,000 / person</small></span></button><button class="collection" data-collection="family"><i>♙</i><span><b>Better, together.</b><small>Family escapes planned with care</small></span></button><button class="collection" data-collection="international"><i>◎</i><span><b>A little further from ordinary.</b><small>Explore international itineraries</small></span></button></div>${travelResults()}`; }

function renderLeads() { const columns = ['New', 'Follow-up', 'Quotation', 'Confirmed', 'Lost']; return pageHead('Leads', 'Track every enquiry from first contact to conversion.', '<button class="btn primary" data-add="leads">＋ Add lead</button><button class="btn" id="leadViewToggle">Table view</button>') + `<div class="filters"><input class="field" id="leadSearch" placeholder="Search leads"><select class="field" id="leadSource"><option>All sources</option><option>Website</option><option>WhatsApp</option><option>Instagram</option><option>Referral</option></select></div><div id="leadKanban" class="kanban">${columns.map(column => `<section class="kan-col"><div class="kan-head"><span>${column}</span><span>${state.leads.filter(row => row.status === column).length}</span></div>${state.leads.filter(row => row.status === column).map(row => `<article class="lead-card"><header><b>${escapeHTML(row.name)}</b><span class="lead-destination">${escapeHTML(row.destination)}</span><small>${dateText(row.date)}</small></header><footer><span class="lead-owner">${escapeHTML(row.owner)}</span><div class="lead-actions"><button class="btn small" data-lead-quote="${escapeHTML(row.id)}">Quote</button><button class="btn small" data-edit="leads" data-id="${escapeHTML(row.id)}">Edit</button></div></footer></article>`).join('')}</section>`).join('')}</div><div id="leadTable" class="hidden">${leadTable(state.leads)}</div>`; }
function leadTable(rows) { return table(['Name', 'Contact', 'Destination', 'Travel date', 'Source', 'Owner', 'Status', 'Action'], rows.map(row => [escapeHTML(row.name), escapeHTML(row.phone), escapeHTML(row.destination), dateText(row.date), escapeHTML(row.source), escapeHTML(row.owner), status(row.status), `<button class="btn small" data-lead-quote="${escapeHTML(row.id)}">Quote</button> <button class="btn small" data-edit="leads" data-id="${escapeHTML(row.id)}">Edit</button>`])); }
function filterLeads() { const needle = ($('#leadSearch')?.value || '').trim().toLowerCase(), source = $('#leadSource')?.value || 'All sources', rows = state.leads.filter(row => (source === 'All sources' || row.source === source) && [row.name, row.phone, row.destination, row.owner].join(' ').toLowerCase().includes(needle)); $('#leadTable').innerHTML = leadTable(rows); $('#leadKanban').classList.add('hidden'); $('#leadTable').classList.remove('hidden'); $('#leadViewToggle').textContent = 'Kanban view'; }
function customerTable(rows) { return table(['Customer ID', 'Customer', 'Mobile', 'Document notes', 'Last trip', 'Action'], rows.map(row => [escapeHTML(row.id), escapeHTML(row.name), escapeHTML(row.phone), escapeHTML(row.documents || '—'), escapeHTML(row.lastTrip || '—'), `<button class="btn small" data-edit="customers" data-id="${escapeHTML(row.id)}">Edit</button>`])); }
function renderCustomers() { return pageHead('Customers', 'Confirmed bookings automatically create or update customer records.', '<button class="btn primary" data-add="customers">＋ Add customer</button>') + `<div class="customer-search"><span aria-hidden="true">⌕</span><input class="field" id="customerSearch" autocomplete="off" placeholder="Search by customer ID, name, mobile, documents or trip" aria-label="Search customers"></div><div id="customerResults">${customerTable(state.customers)}</div>`; }
function filterCustomers() { const needle = ($('#customerSearch')?.value || '').trim().toLowerCase(), rows = state.customers.filter(row => [row.id, row.name, row.phone, row.documents, row.lastTrip].join(' ').toLowerCase().includes(needle)); $('#customerResults').innerHTML = customerTable(rows); }
function renderPackages() { return pageHead('Package library', 'Reusable itinerary templates connected to the travel desk.', '<button class="btn primary" data-add="packages">＋ Add package</button><button class="btn" data-page="discover">Open travel desk</button>') + `<div class="package-grid">${packageCards(state.packages)}</div>`; }
function renderBookings() { const actions = row => `<button class="btn small" data-booking-stage="${escapeHTML(row.id)}">Stage</button> <button class="btn small" data-edit="bookings" data-id="${escapeHTML(row.id)}">Edit</button> ${isAdmin() && row.status === 'Pending' ? `<button class="btn primary small" data-confirm-booking="${escapeHTML(row.id)}">Confirm</button>` : isAdmin() && row.invoice ? `<button class="btn small" data-invoice="${escapeHTML(row.id)}">Invoice</button>` : ''}`; if (!isAdmin()) return pageHead('Bookings', 'Operational booking details. Confirmation and financial values require administrator access.', '<button class="btn primary" data-add="bookings">＋ New booking</button>') + stats([['Total bookings', state.bookings.length], ['Pending', state.bookings.filter(row => row.status === 'Pending').length], ['Confirmed', state.bookings.filter(row => row.status === 'Confirmed').length], ['Upcoming', state.bookings.filter(row => daysUntil(row.departure) >= 0).length]]) + table(['Booking', 'Customer', 'Trip', 'Services', 'Departure', 'Status', 'Action'], state.bookings.map(row => [escapeHTML(row.id), `${escapeHTML(row.customer)}<br><small>${escapeHTML(row.phone)}</small>`, escapeHTML(row.trip), escapeHTML(row.services), dateText(row.departure), status(row.status), actions(row)])); return pageHead('Bookings', 'Track services, confirmation and invoice creation.', '<button class="btn primary" data-add="bookings">＋ New booking</button>') + stats([['Total bookings', state.bookings.length], ['Pending', state.bookings.filter(row => row.status === 'Pending').length], ['Confirmed', state.bookings.filter(row => row.status === 'Confirmed').length], ['Booked value', money(sum(state.bookings, row => row.total))]]) + table(['Booking', 'Customer', 'Trip', 'Services', 'Departure', 'Value', 'Status', 'Action'], state.bookings.map(row => [escapeHTML(row.id), `${escapeHTML(row.customer)}<br><small>${escapeHTML(row.phone)}</small>`, escapeHTML(row.trip), escapeHTML(row.services), dateText(row.departure), money(row.total), status(row.status), actions(row)])); }
function renderVisas() { return pageHead('Visa cases', 'Checklist tracking only—always verify current official destination rules.', '<button class="btn primary" data-add="visas">＋ Add case</button>') + stats([['Active cases', state.visas.filter(row => !['Approved', 'Rejected'].includes(row.status)).length], ['Documents pending', state.visas.filter(row => row.status === 'Documents pending').length], ['Submitted', state.visas.filter(row => row.status === 'Submitted').length], ['Approved', state.visas.filter(row => row.status === 'Approved').length]]) + table(['Applicant', 'Country', 'Appointment', 'Checklist', 'Fee', 'Status', 'Action'], state.visas.map(row => [escapeHTML(row.applicant), escapeHTML(row.country), dateText(row.appointment), `${row.done} / ${row.total}<div class="progress"><i class="p-${Math.round(row.done / row.total * 10) * 10}"></i></div>`, money(row.fee), status(row.status), `<button class="btn small" data-edit="visas" data-id="${escapeHTML(row.id)}">Update</button>`])); }
function paymentStatus(row) { if (row.received >= row.total) return 'Paid'; if (row.due < today()) return 'Overdue'; return row.received > 0 ? 'Part paid' : 'Pending'; }
function renderPayments() { return pageHead('Payments', 'Invoices, receipts and balances saved by the backend.', '<button class="btn primary" data-add="payments">＋ Add invoice</button>') + stats([['Invoiced', money(sum(state.payments, row => row.total))], ['Received', money(sum(state.payments, row => row.received))], ['Outstanding', money(sum(state.payments, row => row.total - row.received))], ['Overdue', state.payments.filter(row => paymentStatus(row) === 'Overdue').length]]) + table(['Invoice', 'Customer', 'Total', 'Received', 'Balance', 'Due', 'Status', 'Action'], state.payments.map(row => [escapeHTML(row.invoice), escapeHTML(row.customer), money(row.total), money(row.received), money(row.total - row.received), dateText(row.due), status(paymentStatus(row)), `<button class="btn small" data-payment-history="${escapeHTML(row.id)}">History</button> <button class="btn primary small" data-payment-receipt="${escapeHTML(row.id)}" ${row.received >= row.total ? 'disabled' : ''}>Record payment</button>`])); }
function renderSuppliers() { return pageHead('Suppliers', 'Saved contacts and commercial notes—no live inventory feed.', '<button class="btn primary" data-add="suppliers">＋ Add supplier</button>') + stats([['Suppliers', state.suppliers.length], ['Available', state.suppliers.filter(row => row.status === 'Available').length], ['Outstanding', money(sum(state.suppliers, row => row.outstanding))], ['Average rating', (sum(state.suppliers, row => row.rating) / Math.max(state.suppliers.length, 1)).toFixed(1)]]) + table(['Supplier', 'Type', 'Location', 'Saved rate', 'Outstanding', 'Rating', 'Availability', 'Action'], state.suppliers.map(row => [escapeHTML(row.name), escapeHTML(row.type), escapeHTML(row.location), money(row.lastRate), money(row.outstanding), `${row.rating} / 5`, status(row.status), `<button class="btn small" data-supplier-ledger="${escapeHTML(row.id)}">Ledger</button> <button class="btn small" data-edit="suppliers" data-id="${escapeHTML(row.id)}">Edit</button>`])); }
function renderStaff() { const owners = [...new Set(['Snehal', 'Amit', 'Neha', ...state.leads.map(row => row.owner)])]; return pageHead('Staff', 'A derived view of lead ownership and conversions.') + table(['Team member', 'Leads', 'Follow-ups due', 'Linked bookings', 'Conversion'], owners.map(owner => { const leads = state.leads.filter(row => row.owner === owner), won = leads.filter(lead => state.bookings.some(booking => booking.customer === lead.name)).length; return [escapeHTML(owner), leads.length, leads.filter(row => row.followup && row.followup <= today() && !['Lost', 'Confirmed'].includes(row.status)).length, won, leads.length ? `${(won / leads.length * 100).toFixed(1)}%` : '0%']; })); }
function renderReports() { const sources = [...new Set(state.leads.map(row => row.source))], destinations = Object.entries(state.bookings.reduce((all, row) => ({ ...all, [row.trip]: (all[row.trip] || 0) + 1 }), {})).sort((a, b) => b[1] - a[1]); return pageHead('Reports', 'Live summaries calculated from CRM records.') + `<div class="grid-2"><section class="card"><div class="card-title"><h2>Lead sources</h2></div>${sources.map(source => { const leads = state.leads.filter(row => row.source === source), won = leads.filter(lead => state.bookings.some(booking => booking.customer === lead.name)).length; return `<div class="activity"><span class="dot"></span><div><p><b>${escapeHTML(source)}</b></p><small>${won}/${leads.length} converted · ${leads.length ? (won / leads.length * 100).toFixed(1) : 0}%</small></div></div>`; }).join('')}</section><section class="card"><div class="card-title"><h2>Top destinations</h2></div>${destinations.map(([destination, count], index) => `<div class="activity"><span class="dot"></span><div><p><b>${index + 1}. ${escapeHTML(destination)}</b></p><small>${count} booking${count === 1 ? '' : 's'}</small></div></div>`).join('') || '<p class="empty">No bookings.</p>'}</section></div>`; }

function quoteTotals(quote = state.quote) { const travellers = Math.max(1, Number(quote.travellers) || 1), base = sum(quote.items || [], row => Number(row.cost) || 0), subtotal = sum(quote.items || [], row => (Number(row.cost) || 0) * (1 + (Number(row.markup) || 0) / 100)), markup = subtotal - base, tax = Math.round(subtotal * (Number(quote.taxRate) || 0)) / 100, total = Math.round((subtotal + tax) * 100) / 100; return { travellers, base, markup, tax, total, perPerson: Math.round(total / travellers * 100) / 100 }; }
function renderQuote() { const quote = state.quote, totals = quoteTotals(); return pageHead('Quotation builder', 'Build, save, print and convert a trip estimate.', '<button class="btn" data-new-quote>New quotation</button>') + `<div class="quote-layout"><section class="card"><form id="quoteForm" class="form-grid"><label>Customer<input name="customer" value="${escapeHTML(quote.customer)}"></label><label>Mobile<input name="phone" value="${escapeHTML(quote.phone)}"></label><label>Email<input name="email" type="email" value="${escapeHTML(quote.email)}"></label><label>Destination<input name="destination" value="${escapeHTML(quote.destination)}"></label><label>Start date<input name="start" type="date" value="${escapeHTML(inputDate(quote.start))}"></label><label>Duration<input name="duration" value="${escapeHTML(quote.duration)}"></label><label>Travellers<input name="travellers" type="number" min="1" max="100" value="${escapeHTML(quote.travellers)}"></label><label>Departure city<input name="departure" value="${escapeHTML(quote.departure)}"></label><label>Tax rate %<input name="taxRate" type="number" min="0" max="100" step="0.01" value="${escapeHTML(quote.taxRate)}"></label><label class="full">Day-wise itinerary<textarea name="itinerary" rows="6">${escapeHTML(quote.itinerary)}</textarea></label><label class="full">Hotels / services / exclusions<textarea name="details" rows="5">${escapeHTML(quote.details)}</textarea></label></form><div class="card-title quote-lines"><h3>Cost items</h3><button class="btn small" data-add-quote-line>＋ Add item</button></div><div id="quoteItems">${(quote.items || []).map((row, index) => `<div class="quote-row"><input class="field" data-quote-item="name" data-index="${index}" value="${escapeHTML(row.name)}" placeholder="Service"><input class="field" data-quote-item="cost" data-index="${index}" inputmode="decimal" value="${escapeHTML(row.cost)}" placeholder="Cost"><input class="field" data-quote-item="markup" data-index="${index}" type="number" min="0" max="500" value="${escapeHTML(row.markup)}" placeholder="Markup %"><button class="btn small danger" data-remove-quote-line="${index}">×</button></div>`).join('') || '<p class="muted">Add at least one cost item.</p>'}</div></section><aside class="card summary"><h3>Quotation summary</h3><div class="summary-row"><span>Base cost</span><b id="quoteBase">${money(totals.base)}</b></div><div class="summary-row"><span>Markup</span><b id="quoteMarkup">${money(totals.markup)}</b></div><div class="summary-row"><span>Tax</span><b id="quoteTax">${money(totals.tax)}</b></div><div class="summary-row total"><span>Total</span><b id="quoteTotal">${money(totals.total)}</b></div><div class="summary-row"><span>Per person</span><b id="quotePerPerson">${money(totals.perPerson)}</b></div><button class="btn primary" data-save-quote>Save quotation</button><button class="btn whatsapp" data-whatsapp-quote><span aria-hidden="true">◉</span> Send on WhatsApp</button><button class="btn" data-print-quote>Print / Save PDF</button><button class="btn" data-copy-quote>Copy summary</button><button class="btn" data-book-quote ${totals.total <= 0 ? 'disabled' : ''}>Create booking</button></aside></div>`; }
function syncQuoteFromDOM() { const form = $('#quoteForm'); if (!form) return; Object.assign(state.quote, Object.fromEntries(new FormData(form))); state.quote.travellers = Number(state.quote.travellers); state.quote.taxRate = Number(state.quote.taxRate); const totals = quoteTotals(); $('#quoteBase').textContent = money(totals.base); $('#quoteMarkup').textContent = money(totals.markup); $('#quoteTax').textContent = money(totals.tax); $('#quoteTotal').textContent = money(totals.total); $('#quotePerPerson').textContent = money(totals.perPerson); }

function renderSettings() { const settings = state.settings; return pageHead('Settings', 'Administrator-only business, security and data controls.') + `<div class="grid-2"><section class="card"><div class="card-title"><h2>Business profile</h2></div><form id="settingsForm" class="form-grid"><label>Business name<input name="business" value="${escapeHTML(settings.business)}" required></label><label>GSTIN<input name="gstin" value="${escapeHTML(settings.gstin)}"></label><label>Phone<input name="phone" value="${escapeHTML(settings.phone)}" required></label><label>Email<input name="email" type="email" value="${escapeHTML(settings.email)}" required></label><label class="full">Address<textarea name="address">${escapeHTML(settings.address)}</textarea></label><label class="full">Payment instructions<textarea name="payment">${escapeHTML(settings.payment)}</textarea></label><label class="full">Quotation terms<textarea name="terms">${escapeHTML(settings.terms)}</textarea></label><button class="btn primary">Save settings</button></form></section><section class="card"><div class="card-title"><h2>Security &amp; data</h2></div><p><b>Signed in as:</b> ${escapeHTML(currentUser.username)} · Administrator</p><p class="muted">Passwords use salted scrypt hashes. Sessions are HttpOnly, SameSite protected, CSRF checked, idle-expiring and role-authorized by the server.</p><div class="actions"><button class="btn" data-change-password>Change password</button><button class="btn" data-export-backup>Export JSON backup</button><button class="btn" data-restore-backup>Restore backup</button></div><hr><p>CRM records are saved in SQLite. Employee accounts cannot access finance, suppliers, reports, backups or settings endpoints.</p><p><b>API health:</b> <span class="success">Connected</span></p></section></div>`; }

function packageDetails(id) { const row = state.packages.find(item => item.id === id); if (!row) return; const days = row.itinerary.split('\n').filter(Boolean); showModal(row.name, `<div class="package-image ${escapeHTML(row.color)}"><img src="${escapeHTML(packagePhoto(row))}" alt="${escapeHTML(row.destination)} destination scenery"><b>${escapeHTML(row.destination)} · ${escapeHTML(row.duration)}</b></div><h3>${escapeHTML(row.route)}</h3><p>${escapeHTML(row.details)}</p><div class="detail-days"><h3>Day-by-day itinerary</h3>${days.map((line, index) => { const [heading, ...body] = line.split('|'); return `<details ${index === 0 ? 'open' : ''}><summary>Day ${index + 1} · ${escapeHTML(heading)}</summary><p>${escapeHTML(body.join('|'))}</p></details>`; }).join('')}</div>`, `<button class="btn" data-close-modal>Close</button><button class="btn" data-edit="packages" data-id="${escapeHTML(row.id)}">Edit</button><button class="btn" data-package-book="${escapeHTML(row.id)}">Create booking</button><button class="btn primary" data-package-quote="${escapeHTML(row.id)}">Make quotation</button>`); }
async function saveExplorer(next) { state.explorer = await api('/api/meta/explorer', { method: 'PUT', body: JSON.stringify(next) }); }
async function rememberSearch(search) { const recent = [search, ...(state.explorer.recent || []).filter(row => JSON.stringify(row) !== JSON.stringify(search))].slice(0, 5); await saveExplorer({ ...state.explorer, recent }); }
function searchFromForm(form) { const data = Object.fromEntries(new FormData(form)); for (const key of ['adults', 'children', 'infants', 'rooms']) data[key] = Number(data[key] || (key === 'adults' || key === 'rooms' ? 1 : 0)); data.mode = travelMode; if (data.trip === 'multi') data.legs = [{ from: data.from, to: data.to, date: data.departure }, ...travelLegs.map((_, index) => ({ from: data[`legFrom${index}`], to: data[`legTo${index}`], date: data[`legDate${index}`] }))]; return data; }
async function runTravelSearch(form) { const search = searchFromForm(form); travelLastSearch = clone(search); await rememberSearch(search); if (travelMode === 'holidays') { packageFilter.query = search.to; render(); return; } travelEstimate = await api('/api/travel/estimate', { method: 'POST', body: JSON.stringify(search) }); render(); }
function loadQuoteFromPackage(id) { const row = state.packages.find(item => item.id === id), search = travelLastSearch || { from: 'Pune', departure: plusDays(today(), 30), adults: 2, children: 0, rooms: 1 }; const travellers = Math.max(1, Number(search.adults || 1) + Number(search.children || 0)); state.quote = { customer: '', phone: '', email: '', destination: row.name, start: search.departure, duration: row.duration, travellers, departure: search.from, itinerary: row.itinerary, details: `${row.details}\nRequested: ${search.rooms || 1} room(s), ${search.adults || 1} adult(s), ${search.children || 0} child(ren).`, taxRate: 5, items: [{ name: `${row.name} · ${travellers} travellers`, cost: row.price * travellers, markup: 0 }] }; closeModal(); navigate('quotations'); }
function loadQuoteFromOffer(index, manualOffer = null) { const offer = manualOffer || travelEstimate?.offers?.[index]; if (!offer || !travelLastSearch) return toast('Search again before using this estimate.'); const search = travelLastSearch; state.quote = { customer: '', phone: '', email: '', destination: offer.route, start: search.departure, duration: search.returnDate ? `${Math.max(0, Math.round((Date.parse(search.returnDate) - Date.parse(search.departure)) / 86400000))} nights` : 'As selected', travellers: search.adults + search.children + search.infants, departure: search.from, itinerary: `${offer.name}|${offer.route}.`, details: `${offer.basis}\nPlanning estimate only. Verify supplier availability, terms and applicable tax.`, taxRate: 5, items: [{ name: `${offer.name} · total allowance`, cost: offer.price, markup: 0 }] }; navigate('quotations'); }
function bookingPresetFromPackage(id) { const row = state.packages.find(item => item.id === id), search = travelLastSearch || { from: 'Pune', departure: plusDays(today(), 30), adults: 2, children: 0 }; const travellers = Math.max(1, search.adults + search.children); return { trip: row.destination, type: row.type, services: `${row.name} · ${travellers} travellers · Hotel, Transfers, Sightseeing${row.flights === 'Included' ? ', Flight allowance' : ''}`, departure: search.departure, return: plusDays(search.departure, row.nights), total: Math.round(row.price * travellers * 1.05 * 100) / 100, taxRate: 5 }; }
function bookingPresetFromOffer(index) { const offer = travelEstimate?.offers?.[index], search = travelLastSearch; if (!offer || !search) throw new Error('Search again before creating a booking.'); return { trip: search.to, type: ['Dubai', 'Tokyo', 'Bali', 'Singapore', 'Japan'].some(city => search.to.toLowerCase().includes(city.toLowerCase())) ? 'International' : 'Domestic', services: `${offer.name}: ${offer.route}; ${offer.basis}`, departure: search.departure, return: search.returnDate || search.departure, total: Math.round(offer.price * 1.05 * 100) / 100, taxRate: 5 }; }
function comparePackages() { const rows = [...selectedPackages].map(id => state.packages.find(row => row.id === id)).filter(Boolean); showModal('Compare getaways', table(['Details', ...rows.map(row => row.name)], [['Destination', ...rows.map(row => escapeHTML(row.route))], ['Duration', ...rows.map(row => escapeHTML(row.duration))], ['Price / person', ...rows.map(row => money(row.price))], ['Flights', ...rows.map(row => escapeHTML(row.flights))], ['Hotel guide', ...rows.map(row => `${row.stars}★`)], ['Style', ...rows.map(row => escapeHTML(row.theme))]])); }

function showBookingStage(id) { const row = state.bookings.find(item => item.id === id), stages = ['Enquiry accepted', 'Supplier options', 'Quotation approved', 'Payment & documents', 'Confirmed']; showModal(`${row.id} · Booking stage`, `<h3>${escapeHTML(row.customer)} · ${escapeHTML(row.trip)}</h3>${stages.map((label, index) => `<div class="activity"><span class="dot"></span><div><p><b>${index + 1}. ${escapeHTML(label)}</b></p><small>${index + 1 < row.stage ? 'Complete' : index + 1 === row.stage ? 'Current stage' : 'Not started'}</small></div></div>`).join('')}`); }
function showPaymentHistory(id) { const row = state.payments.find(item => item.id === id); showModal(`${row.invoice} · Payment history`, table(['Date', 'Amount', 'Method', 'Reference'], (row.receipts || []).map(receipt => [dateText(receipt.date), money(receipt.amount), escapeHTML(receipt.method), escapeHTML(receipt.reference || '—')])) + `<p><b>Balance: ${money(row.total - row.received)}</b></p>`); }
function openReceipt(id) { const row = state.payments.find(item => item.id === id); showModal(`Record payment · ${row.invoice}`, `<p>Outstanding balance: <b>${money(row.total - row.received)}</b></p><form id="receiptForm" class="form-grid" data-id="${escapeHTML(row.id)}"><label>Amount<input name="amount" inputmode="decimal" placeholder="e.g. 25,000.50" required></label><label>Payment date<input name="date" type="date" max="${today()}" value="${today()}" required></label><label>Method<select name="method"><option>UPI</option><option>Bank transfer</option><option>Cash</option><option>Card</option><option>Other</option></select></label><label>Reference / note<input name="reference"></label><p class="error full" id="receiptError"></p></form>`, '<button class="btn" data-close-modal>Cancel</button><button class="btn primary" type="submit" form="receiptForm">Record receipt</button>'); }
function showSupplierLedger(id) { const row = state.suppliers.find(item => item.id === id); showModal(`${row.name} · Ledger`, `<div class="stats"><article class="stat"><span>Saved rate</span><b>${money(row.lastRate)}</b></article><article class="stat"><span>Outstanding</span><b>${money(row.outstanding)}</b></article></div><p><b>Location:</b> ${escapeHTML(row.location)}<br><b>Availability:</b> ${escapeHTML(row.status)}<br><b>Rating:</b> ${row.rating}/5</p><p class="muted">This is saved CRM data. No supplier system or live inventory feed is connected.</p>`); }
function tripReminderMessage(row) { return `Hello ${row.customer}, reminder from ${state.settings.business}: your ${row.trip} trip departs on ${dateText(row.departure)}. Booking ${row.id} is confirmed. Please keep your travel documents ready.`; }
function showNotifications() { const pending = state.bookings.filter(row => row.status === 'Pending').length, visas = state.visas.filter(row => !['Approved', 'Rejected'].includes(row.status)).length, reminders = upcomingTrips(), overdue = isAdmin() ? state.payments.filter(row => paymentStatus(row) === 'Overdue').length : 0; showModal('Operational notifications', `<div class="stats ${isAdmin() ? '' : 'stats-3'}"><article class="stat"><span>Trip reminders due</span><b>${reminders.length}</b></article><article class="stat"><span>Pending bookings</span><b>${pending}</b></article><article class="stat"><span>Active visa cases</span><b>${visas}</b></article>${isAdmin() ? `<article class="stat"><span>Overdue invoices</span><b>${overdue}</b></article>` : ''}</div><section class="notification-list"><div class="card-title"><h3>Departing within three days</h3><span class="muted">Workspace alert + customer message</span></div>${reminders.map(row => `<article class="notification-item"><div><b>${escapeHTML(row.customer)} · ${escapeHTML(row.trip)}</b><small>${dateText(row.departure)} · ${daysUntil(row.departure) === 0 ? 'today' : `in ${daysUntil(row.departure)} day${daysUntil(row.departure) === 1 ? '' : 's'}`}</small></div><button class="btn whatsapp small" data-trip-whatsapp="${escapeHTML(row.id)}">◉ Message customer</button></article>`).join('') || '<p class="empty">No confirmed trips depart in the next three days.</p>'}</section>`); }
function printDocument(title, body, footer = '') { $('#printArea').innerHTML = `<header><h1>${escapeHTML(state.settings.business)}</h1><p>${escapeHTML(state.settings.address)} · ${escapeHTML(state.settings.phone)} · ${escapeHTML(state.settings.email)}</p><h2>${escapeHTML(title)}</h2></header>${body}<footer>${footer || escapeHTML(state.settings.terms)}</footer>`; window.print(); }
function printQuote() { syncQuoteFromDOM(); const quote = state.quote, totals = quoteTotals(); printDocument('Travel quotation', `<p><b>Customer:</b> ${escapeHTML(quote.customer || '—')} · ${escapeHTML(quote.phone || '')}<br><b>Trip:</b> ${escapeHTML(quote.destination)} · ${dateText(quote.start)} · ${escapeHTML(quote.duration)}<br><b>Departure:</b> ${escapeHTML(quote.departure)} · <b>Travellers:</b> ${totals.travellers}</p>${table(['Service', 'Cost', 'Markup'], quote.items.map(row => [escapeHTML(row.name), money(row.cost), `${Number(row.markup) || 0}%`]))}<h2>Total: ${money(totals.total)}</h2><p>Tax: ${money(totals.tax)} · Per person: ${money(totals.perPerson)}</p><h3>Itinerary</h3><p>${escapeHTML(quote.itinerary).replaceAll('\n', '<br>')}</p><h3>Travel details</h3><p>${escapeHTML(quote.details).replaceAll('\n', '<br>')}</p>`); }
function printInvoice(id) { const row = state.bookings.find(item => item.id === id), payment = state.payments.find(item => item.invoice === row.invoice); printDocument(`Invoice ${row.invoice}`, `<p><b>Customer:</b> ${escapeHTML(row.customer)} · ${escapeHTML(row.phone)}<br><b>Trip:</b> ${escapeHTML(row.trip)}<br><b>Services:</b> ${escapeHTML(row.services)}<br><b>Travel dates:</b> ${dateText(row.departure)} – ${dateText(row.return)}</p>${table(['Description', 'Amount'], [[escapeHTML(row.services), money(row.total)]])}<h2>Total: ${money(row.total)}</h2><p>Received: ${money(payment?.received || 0)} · Balance: ${money(row.total - (payment?.received || 0))}</p>`, escapeHTML(state.settings.payment)); }

async function globalSearch(query) { const needle = query.trim().toLowerCase(); if (!needle) return; const packages = state.packages.filter(row => [row.name, row.destination, row.route, row.theme].join(' ').toLowerCase().includes(needle)); if (packages.length) return showModal(`Holiday packages · “${query}”`, `<div class="package-search-list">${packages.slice(0, 24).map(row => `<button class="package-search-result" data-package-details="${escapeHTML(row.id)}"><img src="${escapeHTML(packagePhoto(row))}" alt=""><span><b>${escapeHTML(row.name)}</b><small>${escapeHTML(row.route)} · ${escapeHTML(row.duration)}</small></span><strong>${money(row.price)}</strong></button>`).join('')}</div>${packages.length > 24 ? `<p class="muted">Showing 24 of ${packages.length} packages. Refine your destination search for fewer results.</p>` : ''}`); const groups = [['leads', 'name', 'destination'], ['customers', 'name', 'phone'], ['bookings', 'customer', 'trip'], ['visas', 'applicant', 'country'], ...(isAdmin() ? [['payments', 'customer', 'invoice'], ['suppliers', 'name', 'location']] : [])], results = groups.flatMap(([collection, ...keys]) => state[collection].filter(row => keys.some(key => String(row[key] || '').toLowerCase().includes(needle))).slice(0, 20).map(row => ({ collection, id: row.id, title: row.name || row.customer || row.applicant || row.invoice, detail: row.destination || row.trip || row.country || row.location || '' }))); showModal(`CRM results · “${query}”`, results.length ? `<div class="crm-search-list">${results.map(row => `<button class="activity btn" data-search-result="${escapeHTML(row.collection)}" data-id="${escapeHTML(row.id)}"><span class="dot"></span><span><b>${escapeHTML(row.title)}</b><small>${escapeHTML(row.collection)} · ${escapeHTML(row.detail)}</small></span></button>`).join('')}</div>` : '<p class="empty">No matching packages or CRM records.</p>'); }

document.addEventListener('click', async event => {
  const button = event.target.closest('button'); if (!button) return;
  try {
    if (button.dataset.page) return navigate(button.dataset.page);
    if (button.hasAttribute('data-close-modal')) return closeModal();
    if (button.id === 'profileButton') return showAccount();
    if (button.hasAttribute('data-change-password')) return passwordForm(false);
    if (button.hasAttribute('data-logout')) { await api('/api/auth/logout', { method: 'POST' }); currentUser = null; csrfToken = ''; return showLogin('You have been signed out.'); }
    if (button.dataset.add) return openEditor(button.dataset.add);
    if (button.dataset.edit) { closeModal(); return openEditor(button.dataset.edit, button.dataset.id); }
    if (button.dataset.travelMode) { travelMode = button.dataset.travelMode; travelEstimate = null; travelLegs = []; return render(); }
    if (button.id === 'menuButton') return $('#sidebar').classList.toggle('open');
    if (button.id === 'notificationsButton') return showNotifications();
    if (button.id === 'leadViewToggle') { $('#leadKanban').classList.toggle('hidden'); $('#leadTable').classList.toggle('hidden'); button.textContent = $('#leadTable').classList.contains('hidden') ? 'Table view' : 'Kanban view'; return; }
    if (button.dataset.packageDetails) return packageDetails(button.dataset.packageDetails);
    if (button.dataset.packageQuote) return loadQuoteFromPackage(button.dataset.packageQuote);
    if (button.dataset.packageBook) { closeModal(); return openEditor('bookings', '', bookingPresetFromPackage(button.dataset.packageBook)); }
    if (button.dataset.savePackage) { const id = button.dataset.savePackage, saved = state.explorer.saved.includes(id) ? state.explorer.saved.filter(item => item !== id) : [...state.explorer.saved, id]; await saveExplorer({ ...state.explorer, saved }); render(); return; }
    if (button.hasAttribute('data-saved-filter')) { packageFilter.savedOnly = !packageFilter.savedOnly; render(); return; }
    if (button.hasAttribute('data-clear-package-filter')) { packageFilter = { query: '', budget: 250000, type: 'All', theme: 'All', duration: 'All', flights: 'All', savedOnly: false, sort: 'recommended' }; render(); return; }
    if (button.dataset.collection) { packageFilter = { ...packageFilter, query: '', savedOnly: false }; if (button.dataset.collection === 'budget') packageFilter.budget = 50000; if (button.dataset.collection === 'family') packageFilter.theme = 'Family'; if (button.dataset.collection === 'international') packageFilter.type = 'International'; render(); return; }
    if (button.hasAttribute('data-compare-selected')) return comparePackages();
    if (button.hasAttribute('data-add-leg')) { if (travelLegs.length >= 3) return toast('This prototype supports up to four flight legs.'); const form = $('#travelForm'), data = Object.fromEntries(new FormData(form)); travelLegs.push({ from: travelLegs.at(-1)?.to || data.to, to: '', date: plusDays(travelLegs.at(-1)?.date || data.departure, 2) }); render(); return; }
    if (button.hasAttribute('data-remove-leg')) { travelLegs.splice(Number(button.dataset.removeLeg), 1); render(); return; }
    if (button.hasAttribute('data-recent')) { const row = state.explorer.recent[Number(button.dataset.recent)]; travelMode = row.mode; travelLastSearch = row; packageFilter.query = row.to || ''; if (travelMode === 'holidays') render(); else { travelEstimate = await api('/api/travel/estimate', { method: 'POST', body: JSON.stringify(row) }); render(); } return; }
    if (button.hasAttribute('data-offer-quote')) return loadQuoteFromOffer(Number(button.dataset.offerQuote));
    if (button.hasAttribute('data-offer-book')) return openEditor('bookings', '', bookingPresetFromOffer(Number(button.dataset.offerBook)));
    if (button.dataset.leadQuote) { const row = state.leads.find(item => item.id === button.dataset.leadQuote); state.quote = { ...state.quote, customer: row.name, phone: row.phone, destination: row.destination, start: row.date, departure: 'Pune' }; return navigate('quotations'); }
    if (button.dataset.bookingStage) return showBookingStage(button.dataset.bookingStage);
    if (button.dataset.confirmBooking) { await api(`/api/bookings/${button.dataset.confirmBooking}/confirm`, { method: 'POST' }); await refresh(); render(); toast('Booking confirmed and invoice created.'); return; }
    if (button.hasAttribute('data-whatsapp-quote')) { syncQuoteFromDOM(); const totals = quoteTotals(), phone = String(state.quote.phone || '').replace(/\D/g, ''); if (phone.length < 10) throw new Error('Enter a valid customer mobile number first.'); const message = `${state.settings.business}\nQuotation for ${state.quote.customer || 'Customer'}\nTrip: ${state.quote.destination || 'Travel package'}\nStart: ${dateText(state.quote.start)}\nTotal: ${money(totals.total)}\nSupplier availability and terms require confirmation.`; window.location.assign(whatsappUrl(phone, message)); return; }
    if (button.dataset.tripWhatsapp) { const row = state.bookings.find(item => item.id === button.dataset.tripWhatsapp); window.location.assign(whatsappUrl(row.phone, tripReminderMessage(row))); return; }
    if (button.dataset.invoice) return printInvoice(button.dataset.invoice);
    if (button.dataset.paymentHistory) return showPaymentHistory(button.dataset.paymentHistory);
    if (button.dataset.paymentReceipt) return openReceipt(button.dataset.paymentReceipt);
    if (button.dataset.supplierLedger) return showSupplierLedger(button.dataset.supplierLedger);
    if (button.hasAttribute('data-add-quote-line')) { syncQuoteFromDOM(); state.quote.items.push({ name: '', cost: 0, markup: 0 }); render(); return; }
    if (button.hasAttribute('data-remove-quote-line')) { syncQuoteFromDOM(); state.quote.items.splice(Number(button.dataset.removeQuoteLine), 1); render(); return; }
    if (button.hasAttribute('data-new-quote')) { if (!confirm('Clear the current quotation draft?')) return; state.quote = { customer: '', phone: '', email: '', destination: '', start: '', duration: '', travellers: 2, departure: 'Pune', itinerary: '', details: '', taxRate: 5, items: [] }; await api('/api/meta/quote', { method: 'PUT', body: JSON.stringify(state.quote) }); render(); return; }
    if (button.hasAttribute('data-save-quote')) { syncQuoteFromDOM(); state.quote = await api('/api/meta/quote', { method: 'PUT', body: JSON.stringify(state.quote) }); toast('Quotation saved to the backend.'); return; }
    if (button.hasAttribute('data-print-quote')) return printQuote();
    if (button.hasAttribute('data-copy-quote')) { syncQuoteFromDOM(); const totals = quoteTotals(); await navigator.clipboard.writeText(`${state.settings.business}\nQuotation for ${state.quote.customer || 'customer'}\n${state.quote.destination}\nTotal: ${money(totals.total)}\nSupplier availability and terms require confirmation.`); toast('Quotation summary copied.'); return; }
    if (button.hasAttribute('data-book-quote')) { syncQuoteFromDOM(); const totals = quoteTotals(); return openEditor('bookings', '', { customer: state.quote.customer, phone: state.quote.phone, trip: state.quote.destination, type: ['Dubai', 'Japan', 'Bali', 'Singapore'].some(item => state.quote.destination.includes(item)) ? 'International' : 'Domestic', services: state.quote.items.map(item => item.name).filter(Boolean).join(', '), departure: state.quote.start, return: state.quote.start, total: totals.total, taxRate: state.quote.taxRate }); }
    if (button.hasAttribute('data-export-backup')) { const backup = await api('/api/backup'), link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' })); link.download = `hindavi-crm-backup-${today()}.json`; link.click(); URL.revokeObjectURL(link.href); toast('Backup exported.'); return; }
    if (button.hasAttribute('data-restore-backup')) return $('#restoreFile').click();
    if (button.dataset.searchResult) { closeModal(); navigate(button.dataset.searchResult === 'packages' ? 'packages' : button.dataset.searchResult); return; }
  } catch (error) { toast(error.message); }
});

document.addEventListener('change', event => {
  if (event.target.matches('[data-compare-package]')) { const id = event.target.dataset.comparePackage; if (event.target.checked) { if (selectedPackages.size >= 3) { event.target.checked = false; return toast('Compare up to three packages.'); } selectedPackages.add(id); } else selectedPackages.delete(id); render(); }
  if (event.target.name === 'trip') { const value = event.target.value; $('#returnFields').classList.toggle('hidden', value !== 'return'); $('#addLegButton').classList.toggle('hidden', value !== 'multi'); if (value !== 'multi') { travelLegs = []; $('#multiFields').innerHTML = ''; } }
  if (event.target.id === 'packageSort') { packageFilter.sort = event.target.value; render(); }
  if (event.target.id === 'durationFilter') { packageFilter.duration = event.target.value; render(); }
  if (event.target.id === 'typeFilter') { packageFilter.type = event.target.value; render(); }
  if (event.target.id === 'themeFilter') { packageFilter.theme = event.target.value; render(); }
  if (event.target.id === 'flightFilter') { packageFilter.flights = event.target.value; render(); }
  if (event.target.id === 'leadSource') filterLeads();
});
document.addEventListener('input', event => {
  if (event.target.closest('#quoteForm')) { syncQuoteFromDOM(); return; }
  if (event.target.matches('[data-quote-item]')) { const row = state.quote.items[Number(event.target.dataset.index)]; row[event.target.dataset.quoteItem] = event.target.dataset.quoteItem === 'name' ? event.target.value : parseRupees(event.target.value) || 0; syncQuoteFromDOM(); }
  if (event.target.id === 'budgetFilter') { const value = parseRupees(event.target.value); if (Number.isFinite(value)) packageFilter.budget = value; }
  if (event.target.id === 'leadSearch') filterLeads();
  if (event.target.id === 'customerSearch') filterCustomers();
});
document.addEventListener('focusout', event => { if (event.target.id === 'budgetFilter') render(); });

document.addEventListener('submit', async event => {
  event.preventDefault();
  try {
    if (event.target.id === 'loginForm') { const form = event.target, input = Object.fromEntries(new FormData(form)); $('#loginError').textContent = ''; const auth = await api('/api/auth/login', { method: 'POST', body: JSON.stringify(input) }); currentUser = auth.user; csrfToken = auth.csrfToken; showApp(); if (currentUser.mustChangePassword) { passwordForm(true); return; } await refresh(); render(); return; }
    if (event.target.id === 'passwordForm') { const input = Object.fromEntries(new FormData(event.target)); if (input.newPassword !== input.confirmPassword) throw new Error('New passwords do not match.'); const auth = await api('/api/auth/password', { method: 'PUT', body: JSON.stringify({ currentPassword: input.currentPassword || '', newPassword: input.newPassword }) }); currentUser = auth.user; csrfToken = auth.csrfToken; $('#modal').dataset.locked = ''; closeModal(); showApp(); await refresh(); render(); toast('Password updated securely.'); return; }
    if (event.target.id === 'travelForm') return await runTravelSearch(event.target);
    if (event.target.id === 'editorForm') { const form = event.target, collection = form.dataset.collection, id = form.dataset.id, record = formRecord(form); await api(`/api/${collection}${id ? `/${id}` : ''}`, { method: id ? 'PUT' : 'POST', body: JSON.stringify(record) }); await refresh(); closeModal(); render(); toast('Saved successfully.'); return; }
    if (event.target.id === 'receiptForm') { const form = event.target, value = Object.fromEntries(new FormData(form)); value.amount = parseRupees(value.amount); await api(`/api/payments/${form.dataset.id}/receipts`, { method: 'POST', body: JSON.stringify(value) }); await refresh(); closeModal(); render(); toast('Payment receipt recorded.'); return; }
    if (event.target.id === 'manualEstimateForm') { const value = Object.fromEntries(new FormData(event.target)), amount = parseRupees(value.amount); if (!value.name.trim() || !Number.isFinite(amount) || amount <= 0) throw new Error('Enter a service description and a positive rupee amount.'); return loadQuoteFromOffer(0, { name: value.name.trim(), route: `${travelLastSearch.from} → ${travelLastSearch.to}`, price: amount, basis: 'Manually entered supplier estimate; confirmation required.' }); }
    if (event.target.id === 'settingsForm') { state.settings = await api('/api/meta/settings', { method: 'PUT', body: JSON.stringify(Object.fromEntries(new FormData(event.target))) }); toast('Settings saved.'); return; }
    if (event.target.id === 'globalSearchForm') return await globalSearch($('#globalSearch').value);
  } catch (error) { const target = event.target.querySelector('.error'); if (target) target.textContent = error.message; else toast(error.message); }
});

$('#restoreFile').addEventListener('change', async event => { const file = event.target.files[0]; if (!file) return; try { const value = JSON.parse(await file.text()); if (!confirm(`Replace the current CRM database with “${file.name}”? Export a backup first if needed.`)) return; state = await api('/api/restore', { method: 'POST', body: JSON.stringify(value) }); updateBadges(); render(); toast('Backup restored.'); } catch (error) { toast(error.message); } finally { event.target.value = ''; } });
$('#modal').addEventListener('click', event => { if (event.target === $('#modal')) closeModal(); });
document.addEventListener('keydown', event => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); $('#globalSearch').focus(); } if (event.key === 'Escape') closeModal(); });

async function bootstrap() { try { const auth = await api('/api/auth/me'); currentUser = auth.user; csrfToken = auth.csrfToken; showApp(); if (currentUser.mustChangePassword) { passwordForm(true); return; } await refresh(); render(); } catch (error) { if (error.status === 401) showLogin(); else showLogin(`Backend unavailable: ${error.message}`); } }
await bootstrap();
